public struct MeshContact {
    public var userId: Data
    public var displayName: String
    public var signingPublic: Data
    public var encryptionPublic: Data
    public var fingerprint: String

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(userId: Data, displayName: String, signingPublic: Data, encryptionPublic: Data, fingerprint: String) {
        self.userId = userId
        self.displayName = displayName
        self.signingPublic = signingPublic
        self.encryptionPublic = encryptionPublic
        self.fingerprint = fingerprint
    }
}

#if compiler(>=6)
extension MeshContact: Sendable {}
#endif


extension MeshContact: Equatable, Hashable {
    public static func ==(lhs: MeshContact, rhs: MeshContact) -> Bool {
        if lhs.userId != rhs.userId {
            return false
        }
        if lhs.displayName != rhs.displayName {
            return false
        }
        if lhs.signingPublic != rhs.signingPublic {
            return false
        }
        if lhs.encryptionPublic != rhs.encryptionPublic {
            return false
        }
        if lhs.fingerprint != rhs.fingerprint {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(userId)
        hasher.combine(displayName)
        hasher.combine(signingPublic)
        hasher.combine(encryptionPublic)
        hasher.combine(fingerprint)
    }
}



