public enum MeshAction {
    
    case connect(peerToken: Data
    )
    case sendBytes(linkId: UInt64, data: Data
    )
    case closeLink(linkId: UInt64
    )
    case bundleStored(bundleId: Data
    )
    case bundleDuplicate(bundleId: Data
    )
    case bundleReadyForPeer(linkId: UInt64, bundleId: Data
    )
    case messageUpdated(messageId: Data
    )
    case messageReceived(messageId: Data
    )
    case log(code: String
    )
}


#if compiler(>=6)
extension MeshAction: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeMeshAction: FfiConverterRustBuffer {
    typealias SwiftType = MeshAction

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> MeshAction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connect(peerToken: try FfiConverterData.read(from: &buf)
        )
        
        case 2: return .sendBytes(linkId: try FfiConverterUInt64.read(from: &buf), data: try FfiConverterData.read(from: &buf)
        )
        
        case 3: return .closeLink(linkId: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 4: return .bundleStored(bundleId: try FfiConverterData.read(from: &buf)
        )
        
        case 5: return .bundleDuplicate(bundleId: try FfiConverterData.read(from: &buf)
        )
        
        case 6: return .bundleReadyForPeer(linkId: try FfiConverterUInt64.read(from: &buf), bundleId: try FfiConverterData.read(from: &buf)
        )
        
        case 7: return .messageUpdated(messageId: try FfiConverterData.read(from: &buf)
        )
        
        case 8: return .messageReceived(messageId: try FfiConverterData.read(from: &buf)
        )
        
        case 9: return .log(code: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: MeshAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connect(peerToken):
            writeInt(&buf, Int32(1))
            FfiConverterData.write(peerToken, into: &buf)
            
        
        case let .sendBytes(linkId,data):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(linkId, into: &buf)
            FfiConverterData.write(data, into: &buf)
            
        
        case let .closeLink(linkId):
            writeInt(&buf, Int32(3))
            FfiConverterUInt64.write(linkId, into: &buf)
            
        
        case let .bundleStored(bundleId):
            writeInt(&buf, Int32(4))
            FfiConverterData.write(bundleId, into: &buf)
            
        
        case let .bundleDuplicate(bundleId):
            writeInt(&buf, Int32(5))
            FfiConverterData.write(bundleId, into: &buf)
            
        
        case let .bundleReadyForPeer(linkId,bundleId):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(linkId, into: &buf)
            FfiConverterData.write(bundleId, into: &buf)
            
        
        case let .messageUpdated(messageId):
            writeInt(&buf, Int32(7))
            FfiConverterData.write(messageId, into: &buf)
            
        
        case let .messageReceived(messageId):
            writeInt(&buf, Int32(8))
            FfiConverterData.write(messageId, into: &buf)
            
        
        case let .log(code):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(code, into: &buf)
            
        }
    }
}


